SIGN_BY_KIND = {"sale": 1, "fee": 1, "refund": -1, "credit": -1}
UNIT_BY_KIND = {"sale": 1, "refund": -1}
ROUND_BY_NAME = {"half_up": ROUND_HALF_UP, "half_even": ROUND_HALF_EVEN,
                 "half_down": ROUND_HALF_DOWN}
